SET search_path=vcm,pg_catalog;
CREATE TABLE indicators(id text PRIMARY KEY,name text NOT NULL,unit text NOT NULL);
CREATE TABLE indicator_rule_versions(indicator_id text NOT NULL REFERENCES indicators(id),version text NOT NULL,availability text NOT NULL CHECK(availability IN('available','pending')),criteria text,source text,PRIMARY KEY(indicator_id,version),CHECK(availability<>'available' OR (criteria IS NOT NULL AND source IS NOT NULL)));
CREATE TABLE indicator_targets(indicator_id text NOT NULL REFERENCES indicators(id),period int NOT NULL CHECK(period BETWEEN 1900 AND 9999),target numeric CHECK(target>=0),source text NOT NULL,PRIMARY KEY(indicator_id,period));
CREATE TABLE indicator_contributions(id text PRIMARY KEY,case_id text NOT NULL REFERENCES cases(id),presence_id text,activity_id text,indicator_id text NOT NULL,rule_version text NOT NULL,period int NOT NULL,value numeric NOT NULL CHECK(value>=0),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','validated','rejected')),actor_id text NOT NULL REFERENCES principals(id),version int NOT NULL DEFAULT 1 CHECK(version>0),validated_by text REFERENCES users(principal_id),validated_at timestamptz,FOREIGN KEY(indicator_id,rule_version) REFERENCES indicator_rule_versions,FOREIGN KEY(indicator_id,period) REFERENCES indicator_targets,FOREIGN KEY(case_id,presence_id) REFERENCES presence_records(case_id,id),FOREIGN KEY(case_id,activity_id) REFERENCES activity_records(case_id,id),CHECK(num_nonnulls(presence_id,activity_id)=1),CHECK(indicator_id<>'4.2.5' OR (presence_id IS NOT NULL AND value=1)),CHECK(status<>'validated' OR (validated_by IS NOT NULL AND validated_at IS NOT NULL)),UNIQUE(case_id,id));
CREATE UNIQUE INDEX contribution_presence_key ON indicator_contributions(presence_id,indicator_id,period) WHERE presence_id IS NOT NULL;
CREATE UNIQUE INDEX contribution_activity_key ON indicator_contributions(activity_id,indicator_id,period) WHERE activity_id IS NOT NULL;
CREATE TABLE contribution_evidences(contribution_id text NOT NULL,case_id text NOT NULL,evidence_id text NOT NULL,evidence_version int NOT NULL CHECK(evidence_version>0),PRIMARY KEY(contribution_id,evidence_id),FOREIGN KEY(case_id,contribution_id) REFERENCES indicator_contributions(case_id,id),FOREIGN KEY(case_id,evidence_id) REFERENCES evidences(case_id,id));
CREATE TABLE case_snapshots(case_id text NOT NULL REFERENCES cases(id),version int NOT NULL CHECK(version>0),payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),actor_id text NOT NULL REFERENCES principals(id),captured_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(case_id,version));
CREATE TRIGGER snapshot_immutable BEFORE UPDATE OR DELETE ON case_snapshots FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE institutional_cuts(id text PRIMARY KEY,name text NOT NULL,period text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','review','ready','closed')),response text,version int NOT NULL DEFAULT 1 CHECK(version>0),protected_object_id text NOT NULL UNIQUE REFERENCES protected_objects(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER cut_protect BEFORE INSERT ON institutional_cuts FOR EACH ROW EXECUTE FUNCTION protect_object('cut');
CREATE TABLE cut_revisions(cut_id text NOT NULL REFERENCES institutional_cuts(id),version int NOT NULL CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(cut_id,version));
CREATE TABLE cut_cases(cut_id text NOT NULL REFERENCES institutional_cuts(id),cut_version int NOT NULL CHECK(cut_version>0),case_id text NOT NULL,case_version int NOT NULL,PRIMARY KEY(cut_id,cut_version,case_id),FOREIGN KEY(case_id,case_version) REFERENCES case_snapshots(case_id,version));
CREATE TRIGGER cut_cases_immutable BEFORE UPDATE OR DELETE ON cut_cases FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE cut_observations(id text PRIMARY KEY,cut_id text NOT NULL REFERENCES institutional_cuts(id),case_id text NOT NULL REFERENCES cases(id),category text NOT NULL,text text NOT NULL,responsible_id text REFERENCES principals(id),responsible_label text,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','resolved')),resolution text,resolved_at timestamptz,version int NOT NULL DEFAULT 1 CHECK(version>0),CHECK(status<>'resolved' OR (resolution IS NOT NULL AND resolved_at IS NOT NULL)));
CREATE TABLE report_runs(id text PRIMARY KEY,object_id text NOT NULL REFERENCES protected_objects(id),filters jsonb NOT NULL,rule_version text NOT NULL,as_of timestamptz NOT NULL,actor_id text NOT NULL REFERENCES principals(id),created_at timestamptz NOT NULL DEFAULT now(),data_references jsonb NOT NULL);
INSERT INTO indicators VALUES('4.2.5','Presencias en la sociedad','presencias'),('4.2.2','Proyectos','proyectos'),('4.2.3','Participación estudiantil','estudiantes'),('4.2.9','Difusión','acciones'),('8.1.3','Movilidad','movilidades');
INSERT INTO indicator_rule_versions SELECT id,'PO-2026.09-v1',CASE WHEN id='4.2.5' THEN 'available' ELSE 'pending' END,CASE WHEN id='4.2.5' THEN 'Presencia validada elegible del período, valor 1, evidencia revisada y sin duplicación.' END,'PO 2026.09; criterios completos solo 4.2.5' FROM indicators;
INSERT INTO indicator_targets VALUES('4.2.5',2026,14,'PO 2026.09'),('4.2.2',2026,2,'PO 2026.09'),('4.2.3',2026,240,'PO 2026.09'),('4.2.9',2026,2,'PO 2026.09'),('8.1.3',2026,6,'PO 2026.09');
